{
#!/usr/bin/env bash
source /etc/crypto-policies/back-ends/opensshserver.config
source /etc/sysconfig/sshd
[ -e "$(sshd -T $OPTIONS $CRYPTO_POLICY | awk '$1 == "banner" {print
$2}')" ] && cat "$(sshd -T $OPTIONS $CRYPTO_POLICY | awk '$1 == "banner"
{print $2}')"
}
